from __future__ import annotations

import sys

import rclpy

from apex_backend.ros_state import ApexStateNode
from apex_backend.service_manager import ServiceManager


def main() -> int:
    manager = ServiceManager()

    if not rclpy.ok():
        rclpy.init()

    node = ApexStateNode()
    try:
        robot_status = manager.get_status("robot")
        allowed, reason = node.require_robot_service_active(robot_status)
        if allowed:
            print("Teleop guard passed: Robot Control service is active")
            return 0

        print(f"Teleop guard rejected start: {reason}", file=sys.stderr)
        return 1
    finally:
        node.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()


if __name__ == "__main__":
    raise SystemExit(main())
